(function(){"use strict";const t="cookies_aceptadas";let c=localStorage.getItem(t)==="true";window.OasisCookies={accepted:()=>c},document.addEventListener("DOMContentLoaded",()=>{if(c)return;document.body.classList.add("cookies-blocked");const e=document.createElement("div");e.className="cookies-overlay",e.innerHTML=`
      <div class="cookies-card">
        <p class="eyebrow">COOKIES</p>
        <h2 class="cookies-title">Tu experiencia en Oasis</h2>
        <p class="cookies-text" id="cookiesMsg">Esta web usa cookies para que cargue r\xE1pido, guardar tu b\xFAsqueda y mejorar tu experiencia. Si no aceptas las cookies, la web no cargar\xE1 correctamente.</p>
        <div class="cookies-config" id="cookiesConfig">
          <label><input type="checkbox" checked disabled> Cookies necesarias</label>
          <label><input type="checkbox" id="cPerf"> Cookies de rendimiento</label>
          <label><input type="checkbox" id="cAds"> Cookies de publicidad</label>
        </div>
        <div class="cookies-actions" id="cookiesActions">
          <button class="btn btn-orange" id="cAccept">ACEPTAR TODO</button>
          <button class="btn btn-ghost" id="cReject">RECHAZAR</button>
          <button class="btn btn-ghost" id="cSettings">VER CONFIGURACI\xD3N</button>
        </div>
        <a class="cookies-link" href="cookies.html">Ver Pol\xEDtica de Cookies</a>
      </div>`,document.body.appendChild(e);const o=s=>{localStorage.setItem(t,"true"),localStorage.setItem("cookies_config",JSON.stringify({necesarias:!0,rendimiento:s?!0:!!document.getElementById("cPerf")?.checked,publicidad:s?!0:!!document.getElementById("cAds")?.checked})),location.reload()};document.getElementById("cAccept").onclick=()=>o(!0),document.getElementById("cSettings").onclick=()=>{document.getElementById("cookiesConfig").classList.add("show")},document.getElementById("cReject").onclick=()=>{document.getElementById("cookiesMsg").textContent="Debes aceptar las cookies para usar Oasis Rent A Car",document.getElementById("cookiesActions").innerHTML='<button class="btn btn-orange" id="cAccept2">ACEPTAR COOKIES</button>',document.getElementById("cAccept2").onclick=()=>o(!0)}})})();
